import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"Getting started","description":"","frontmatter":{},"headers":[],"relativePath":"guide/getting-started.md","filePath":"guide/getting-started.md","lastUpdated":1787003086000}`),a={name:`guide/getting-started.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to “Getting started”">​</a></h1><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to “Requirements”">​</a></h2><ul><li>Node.js 22 or newer (24 recommended — it is the active LTS line)</li><li>A FreshRSS instance, developed and verified against 1.29</li></ul><h2 id="_1-enable-the-api-in-freshrss" tabindex="-1">1. Enable the API in FreshRSS <a class="header-anchor" href="#_1-enable-the-api-in-freshrss" aria-label="Permalink to “1. Enable the API in FreshRSS”">​</a></h2><p>Two separate settings, and both are needed:</p><ol><li><strong>Settings → Authentication →</strong> tick <strong>&quot;Allow API access&quot;</strong>.</li><li><strong>Settings → Profile → API management →</strong> set an <strong>API password</strong>.</li></ol><div class="warning custom-block"><p class="custom-block-title">The API password is not your login password</p><p>FreshRSS stores it separately (as <code>apiPasswordHash</code>) and the Google Reader API only ever checks that one. Using the web login password produces a 401 that looks like a typo. The upside: you can rotate the API password on its own without touching your own login.</p></div><h2 id="_2-check-it-from-the-shell" tabindex="-1">2. Check it from the shell <a class="header-anchor" href="#_2-check-it-from-the-shell" aria-label="Permalink to “2. Check it from the shell”">​</a></h2><p>Before wiring up a client, confirm the API answers. <code>ClientLogin</code> returns three lines of plain text and the <code>Auth=</code> value is the token every later call carries:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#953800;--shiki-dark:#FFA657;">curl</span><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;"> -s</span><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;"> -X</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> POST</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;"> \\</span></span>
<span class="line"><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;">  -d</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> &#39;Email=alice&#39;</span><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;"> -d</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> &#39;Passwd=YOUR_API_PASSWORD&#39;</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;"> \\</span></span>
<span class="line"><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">  https://rss.example.com/api/greader.php/accounts/ClientLogin</span></span></code></pre></div><ul><li><code>Auth=alice/…</code> — working.</li><li><code>HTTP 401</code> — wrong password, or you used the login password.</li><li><code>HTTP 503</code> — the API is disabled; go back to step 1.</li><li>An HTML page — <code>FRESHRSS_URL</code> is not the instance root.</li></ul><h2 id="_3-run-the-server" tabindex="-1">3. Run the server <a class="header-anchor" href="#_3-run-the-server" aria-label="Permalink to “3. Run the server”">​</a></h2><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">FRESHRSS_URL</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">https://rss.example.com</span><span style="--shiki-light:#953800;--shiki-dark:#FFA657;"> \\</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">FRESHRSS_USER=alice </span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">\\</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">FRESHRSS_API_PASSWORD=... </span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">\\</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">npx </span><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;">-y</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> @ni-c/freshrss-mcp</span></span></code></pre></div><p>It speaks <a href="https://modelcontextprotocol.io" target="_blank" rel="noreferrer">MCP</a> over stdio, so on its own it just waits on stdin — that is correct behaviour. Point a client at it next.</p><div class="tip custom-block"><p class="custom-block-title">It starts without credentials on purpose</p><p>With nothing configured the server still completes the handshake and lists all its tools; every call then fails with these setup instructions. That is what lets registry sandboxes and the MCP Inspector enumerate the tools without an account.</p></div><h2 id="_4-first-calls" tabindex="-1">4. First calls <a class="header-anchor" href="#_4-first-calls" aria-label="Permalink to “4. First calls”">​</a></h2><p>Ask your client for <code>get_user_info</code> — it is the cheapest credential check and returns the FreshRSS account you are authenticated as. Then <code>list_feeds</code>, which gives you the numeric <code>feedId</code> values every other tool takes as <code>feed_id</code>.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to “Next”">​</a></h2><ul><li><a href="/guide/clients">Connecting clients</a></li><li><a href="/guide/configuration">Configuration</a></li></ul>`,19)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};